import{_ as l,o as i,c as e,X as t}from"./chunks/framework.92e7fb7b.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/fe-sumary/2024-plan.md","filePath":"blogs/fe-sumary/2024-plan.md"}'),o={name:"blogs/fe-sumary/2024-plan.md"},a=t('<h2 id="_2023-总结" tabindex="-1">2023 总结 <a class="header-anchor" href="#_2023-总结" aria-label="Permalink to &quot;2023 总结&quot;">​</a></h2><h2 id="这一年-我取得了一些不错的成绩。" tabindex="-1">这一年，我取得了一些不错的成绩。 <a class="header-anchor" href="#这一年-我取得了一些不错的成绩。" aria-label="Permalink to &quot;这一年，我取得了一些不错的成绩。&quot;">​</a></h2><ul><li><p><strong>技术钻研：</strong></p><ul><li>服务端渲染应用落地、docker compose部署、二开</li><li>用react的 useDapp 发布了自己的web3测试链</li><li>c# webview落地word插件、发布实践、oneClick部署</li><li>electron 网盘应用源码精读、调试、electron原理书泛读</li><li>3d 钻研了revit转glb、drao模型压缩、three.js模型渲染、revit模型选然后 构建选择</li><li>jssip renegotiate落地语音通话转视频通话的处理</li><li>自己前后端、部署做了rdic 这个应用（支持自建单词本、支持共享、修改、单词发音的应用，针对小孩子学英语的场景），技术栈spring boot、vue3 ts</li><li>微前端调研、qiankun项目落地、wsl nginx部署、微前端权限管理设计落地</li><li>读完了《vue.js设计与实现》、《React技术揭秘》、《深入浅出electron原理、工程与实践》等书籍。</li><li>antd g6库，用 svg图 画类3d的图。 ...</li></ul></li><li><p><strong>方法论：</strong></p><ul><li>重视GitHub issue、google、官网文档；不看百度、csdn</li><li>深入理解本质的技术点后 不只是靠模糊的调试和随机的尝试，能成倍提高效率</li></ul></li><li><p><strong>好的方面：</strong></p><ul><li>脸皮变厚了</li></ul></li></ul><h2 id="当然-也有一些需要提升的地方。" tabindex="-1">当然，也有一些需要提升的地方。 <a class="header-anchor" href="#当然-也有一些需要提升的地方。" aria-label="Permalink to &quot;当然，也有一些需要提升的地方。&quot;">​</a></h2><ul><li><p><strong>任务管理：</strong></p><ul><li>目标管理意识较差、严格工时评估的能力差，需求评审不够严谨</li><li>松散的目标意识，如saas中，错误估计整体提测时间</li><li>需求侧不确定的情况下、花很多时间做一些不确定的需求，重复劳动</li></ul></li><li><p><strong>团队管理协调：</strong></p><ul><li>团队进度滞后，只是自己默默承担</li><li>不敢分bug、不敢问成员进度、怕招人口舌</li></ul></li><li><p><strong>封装组件：</strong></p><ul><li>缺少大的整体规划，如设计机构saas中的组件库规划</li><li>过于专注于技术测，但缺少对产品本身、交互的钻研，需求侧未确定导致的变动返工多</li></ul></li><li><p><strong>技能和知识增长</strong></p><ul><li>其实还有一些翻了一部分的书、看了一部分的视频课程；但是没有写清楚为什么不看了，也应该留存一些笔记，过后翻阅；</li></ul></li></ul><h2 id="新的一年的计划" tabindex="-1">新的一年的计划： <a class="header-anchor" href="#新的一年的计划" aria-label="Permalink to &quot;新的一年的计划：&quot;">​</a></h2><ul><li><strong>持续长跑 按季度复盘</strong><ul><li>娱乐消遣控制在每周2天左右</li><li>学习打卡 每周至少3天 时间不限 需要有学习产出的记录（笔记、代码库）</li></ul></li><li><strong>coding</strong><ul><li>沉淀代码资产，不限于工具库、ui库</li><li>重视输出； <ul><li>少些demo项目 多些深入探索</li><li>要有产出成果 仓库开源、or形成相应的技术文章； <ul><li>记笔记，主要是过后自己翻阅可以加深理解；分享给他人的内容，当然需要再深度加工产出博客</li></ul></li></ul></li></ul></li><li><strong>生活方面</strong><ul><li>english first</li><li>练刀工，厨艺精进</li><li>每周2次运动 时间不限</li><li>改掉臭毛病 <ul><li>做的不对的时候，需要承认不行</li><li>不自夸</li><li>不给别人负面的评价</li></ul></li><li>关注家人的心理健康 <ul><li>定期组织集体的运动、露营、短途旅行</li><li>给家人做饭</li></ul></li><li>新家装修 <ul><li>风格 整体方案确认</li><li>初步定设计图</li><li>TODO</li></ul></li></ul></li></ul><p>新的一年，大家都走好运。</p><blockquote><hr><p>Keep looking until you find it. Don&#39;t settle. 赶路的同时 也要边享受生活</p><hr></blockquote>',9),r=[a];function s(n,u,c,p,d,g){return i(),e("div",null,r)}const b=l(o,[["render",s]]);export{_ as __pageData,b as default};
